pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        uint256 amt = 10;
        vm.deal(caller, amt);

        vm.prank(caller);
        c.play{value: amt}();

        uint256 p = c.pot();
        assertTrue(p == 0 || p == amt);
    }
}
